using UnityEditor;
using System;
using System.IO;
using System.Collections.Generic;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            const string folder = "Assets/NfsMw/Content/World/Maps/Rockport/Trees/Prefabs/";
            Directory.CreateDirectory(folder);
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
            var source = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NfsMw/Content/World/Models/RockportTrees/NativeTreePrototypes.gltf");
            if (!source)
                throw new IOException("Tree prototype model not imported");
            var nodes = new Dictionary<string, GameObject>();
            foreach (var t in source.GetComponentsInChildren<Transform>(true))
                nodes[t.name] = t.gameObject;
            const string materialsFolder = "Assets/NfsMw/Content/World/Maps/Rockport/Trees/Materials/";
            Directory.CreateDirectory(materialsFolder);
            AssetDatabase.Refresh();
            var materials = new Dictionary<Material, Material>();
            foreach (var renderer in source.GetComponentsInChildren<MeshRenderer>(true))
                foreach (var original in renderer.sharedMaterials)
                    if (!materials.ContainsKey(original))
                    {
                        string path = materialsFolder + original.name + ".mat";
                        var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                        if (!material)
                        {
                            material = new Material(original);
                            AssetDatabase.CreateAsset(material, path);
                        }

                        material.enableInstancing = true;
                        EditorUtility.SetDirty(material);
                        materials.Add(original, material);
                    }

            var names = File.ReadAllLines("Assets/NfsMw/Content/World/Maps/Rockport/Trees/prototypes.tsv");
            int created = 0, total = 0;
            AssetDatabase.StartAssetEditing();
            try
            {
                foreach (var name in names)
                {
                    string path = folder + name + ".prefab";
                    var existing = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                    bool ready = existing;
                    if (existing)
                        foreach (var renderer in existing.GetComponentsInChildren<MeshRenderer>(true))
                            foreach (var mat in renderer.sharedMaterials)
                                if (!AssetDatabase.GetAssetPath(mat).StartsWith(materialsFolder))
                                    ready = false;
                    if (ready)
                    {
                        total++;
                        continue;
                    }

                    if (created >= 400)
                        continue;
                    if (!nodes.TryGetValue(name, out var node))
                        throw new IOException("Missing tree prototype node " + name);
                    var obj = UnityEngine.Object.Instantiate(node);
                    obj.name = name;
                    obj.transform.SetParent(null);
                    obj.transform.localPosition = Vector3.zero;
                    obj.transform.localRotation = Quaternion.identity;
                    obj.transform.localScale = Vector3.one;
                    try
                    {
                        var renderers = obj.GetComponentsInChildren<MeshRenderer>(true);
                        if (renderers.Length == 0)
                            throw new IOException("No tree renderers " + name);
                        foreach (var renderer in renderers)
                        {
                            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.TwoSided;
                            var mapped = renderer.sharedMaterials;
                            for (int m = 0; m < mapped.Length; m++)
                            {
                                if (!mapped[m] || !materials.TryGetValue(mapped[m], out var material))
                                    throw new IOException("Missing tree material " + name);
                                mapped[m] = material;
                            }

                            renderer.sharedMaterials = mapped;
                        }

                        var lod = obj.GetComponent<LODGroup>();
                        if (!lod)
                            lod = obj.AddComponent<LODGroup>();
                        lod.SetLODs(new[]{new LOD(.00001f, renderers)});
                        lod.RecalculateBounds();
                        PrefabUtility.SaveAsPrefabAsset(obj, path, out bool saved);
                        if (!saved)
                            throw new IOException("Could not save tree prefab " + name);
                        created++;
                        total++;
                    }
                    finally
                    {
                        UnityEngine.Object.DestroyImmediate(obj);
                    }
                }
            }
            finally
            {
                AssetDatabase.StopAssetEditing();
            }

            AssetDatabase.SaveAssets();
            File.WriteAllText("Art/RockportTrees/Source/prefab-progress.txt", total + "/" + names.Length);
            result.Log("Created " + created + " tree prefabs; total " + total + " / " + names.Length);
        }
    }
}",
    "result": "Command executed successfully."
  }
}

